package com.lockwallet.core.solana

import com.lockwallet.core.crypto.Bip39
import com.lockwallet.core.crypto.DerivationProfile
import com.lockwallet.core.crypto.Slip10Ed25519
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * End-to-end: mnemonic -> BIP-39 seed -> SLIP-0010 -> Ed25519 pubkey -> Base58 address.
 * Spec §23.1 expected addresses are hard-coded here exactly as transcribed from the spec PDF, independent
 * of the oracle fixture (which was generated by two other implementations and also matches).
 */
class AddressDerivationTest {
    private val mnemonic = "neither lonely flavor argue grass remind eye tag avocado spot unusual intact"

    private fun address(seed: ByteArray, profile: DerivationProfile, account: Int): String =
        Slip10Ed25519.deriveSolanaKey(seed, profile, account).use { SolanaPublicKey.of(it.publicKey()).toBase58() }

    @Test fun spec231ThreeAddressesByteForByte() {
        Bip39.mnemonicToSeed(mnemonic.toCharArray()).use { seed ->
            seed.withBytes { s ->
                assertEquals("5vftMkHL72JaJG6ExQfGAsT2uGVHpRR7oTNUPMs68Y2N", address(s, DerivationProfile.PRIMARY, 0))
                assertEquals("GcXbfQ5yY3uxCyBNDPBbR5FjumHf89E7YHXuULfGDBBv", address(s, DerivationProfile.PRIMARY, 1))
                assertEquals("ZtSqp8BQkKFvahawCS9Mf15gzFuedeWWDkYap3qQEe4", address(s, DerivationProfile.LEGACY_LEDGER, 0))
            }
        }
    }

    @Test fun spec231FixtureAgreesWithBothOracles() {
        val f = SolanaFixtures.json("lockwallet-spec-23-1.json")
        Bip39.mnemonicToSeed(f["mnemonic"].asString.toCharArray()).use { seed ->
            seed.withBytes { s ->
                f.getAsJsonArray("derivations").forEach {
                    val o = it.asJsonObject
                    val got = address(s, DerivationProfile.valueOf(o["profile"].asString), o["account_index"].asInt)
                    assertEquals(o["address_oracle1_bip_utils"].asString, got)
                    assertEquals(o["address_oracle2_solders"].asString, got)
                }
            }
        }
    }

    @Test fun oracleDerivationsAllSizesProfilesAndMaxIndex() {
        val vectors = SolanaFixtures.json("oracle-derivations.json").getAsJsonArray("vectors")
        var checked = 0
        vectors.forEach { v ->
            val o = v.asJsonObject
            Bip39.mnemonicToSeed(o["mnemonic"].asString.toCharArray()).use { seed ->
                seed.withBytes { s ->
                    o.getAsJsonArray("derivations").forEach { d ->
                        val x = d.asJsonObject
                        assertEquals(x["path"].asString, x["address"].asString,
                            address(s, DerivationProfile.valueOf(x["profile"].asString), x["account_index"].asInt))
                        checked++
                    }
                }
            }
        }
        assertEquals(15 * 8, checked)
        val words24 = vectors.count { it.asJsonObject["mnemonic"].asString.split(' ').size == 24 }
        assertEquals("24-word vectors present", 3, words24)
    }
}
